    getTranslation(o1.worldTransform, o1.meshPart.center, tmpV1);
    getTranslation(o2.worldTransform, o2.meshPart.center, tmpV2);
    final Camera currentCamera = this.camera;
    if (currentCamera == null) {
      throw new IllegalStateException("Camera must not be null when comparing renderables");
    }
    final float dst =
        (int) (1000f * currentCamera.position.dst2(tmpV1))
            - (int) (1000f * currentCamera.position.dst2(tmpV2));
    final int result = dst < 0 ? -1 : (dst > 0 ? 1 : 0);
    return b1 ? -result : result;
